-- Creator storefronts and moderation queue.
create table public.marketplace_seller_profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null check(char_length(display_name) between 2 and 80),handle text not null unique check(handle ~ '^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$'),bio text not null default '',website_url text,avatar_url text,banner_url text,verification_status text not null default 'unverified' check(verification_status in ('unverified','pending','verified','rejected')),sales_count bigint not null default 0,rating_average numeric(3,2),rating_count bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.marketplace_moderation_cases(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.marketplace_listings(id) on delete cascade,seller_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in ('pending','approved','rejected','needs_changes')),risk_flags text[] not null default '{}',notes text,reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now());
alter table public.marketplace_seller_profiles enable row level security;alter table public.marketplace_seller_profiles force row level security;alter table public.marketplace_moderation_cases enable row level security;alter table public.marketplace_moderation_cases force row level security;revoke all on public.marketplace_seller_profiles,public.marketplace_moderation_cases from anon,authenticated;grant select,insert,update on public.marketplace_seller_profiles to authenticated;grant select on public.marketplace_moderation_cases to authenticated;grant all on public.marketplace_seller_profiles,public.marketplace_moderation_cases to service_role;
create policy marketplace_seller_profiles_read on public.marketplace_seller_profiles for select to authenticated using(true);create policy marketplace_seller_profiles_insert on public.marketplace_seller_profiles for insert to authenticated with check(user_id=(select auth.uid()) and verification_status='unverified' and sales_count=0 and rating_count=0);create policy marketplace_seller_profiles_update on public.marketplace_seller_profiles for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy marketplace_moderation_seller_read on public.marketplace_moderation_cases for select to authenticated using(seller_id=(select auth.uid()));